def trans(x):
    x=x.replace("ı","i").replace("İ","i")
    x=unicodedata.normalize("NFKD",x)
    x="".join(ch for ch in x if not unicodedata.combining(ch))
    return re.sub(r"[^A-Za-z0-9 '\-]","",x)[:90]
with GoalAPI(os.environ["GOAL_API_KEY"],timeout=20,max_retries=0) as api:
    print("REQUEST_COUNT",len(INPUT))
    for i,p in enumerate(INPUT):
        name=p["name"]
        try:
            result=api.players.search(trans(name),limit=25)
            candidates=result.get("data",[])
            if not isinstance(candidates,list):candidates=[]
            out=[]
            for o in candidates:
                out.append({"name":o.get("name"),"type":o.get("type"),"age":o.get("age"),"birthdate":o.get("birthdate"),"team":(o.get("team") or {}).get("name"),"apiId":o.get("apiId"),"id":o.get("id")})
            print("ROLE_SEARCH",json.dumps({"requested":p,"hits":out[:18]},ensure_ascii=False,separators=(",",":")))
        except Exception as e:
            print("ROLE_ERROR",name,type(e).__name__,str(e)[:100])
        if i%20==0:print("ROLE_PROGRESS",i+1,len(INPUT))
